(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-1201","batch":"25","category":"Categoria B","question":"Pe drumurile publice prevăzute cu minimum 3 benzi pe sens, atunci când conducătorii a două vehicule circulă în aceeași direcție, dar pe benzi diferite, și intenționează să se înscrie pe banda liberă dintre ei, această bandă va fi ocupată de:","answers":["Vehiculul care circulă pe banda din stânga, față de cel care circulă pe banda din dreapta","Vehiculul care circulă pe banda din dreapta, față de cel care circulă pe banda din stânga","Vehiculul care circulă cu viteza maximă admisă pe sectorul de drum respectiv"],"correctIndices":[0],"correct":0,"explanation":"Conform legislației rutiere, pe un drum public cu cel puțin 3 benzi pe sens, dacă doi conducători de vehicule care circulă în aceeași direcție doresc să se înscrie pe banda liberă dintre ei, cel care se află pe banda din dreapta este obligat să acorde prioritate celui de pe banda din stânga, permițându-i acestuia să ocupe banda liberă dintre ei. Conducătorul vehiculului aflat pe banda din dreaptaNUare prioritate în această situație. Legislația rutieră prevede în mod clar că acesta trebuie să permită vehiculului de pe banda din stânga să ocupe banda liberă dintre ei. Prin urmare, varianta B este incorectă. Prioritatea de înscriere pe banda liberă dintre două vehicule aflate pe benzi adiacenteNUdepinde de viteza lor de deplasare. Legislația rutieră stabilește criteriul priorității în funcție de poziția vehiculelor pe benzi, nu de viteza maximă admisă. Chiar dacă un vehicul circulă cu viteza maximă legală,acest aspect nu îi conferă automat dreptul de a ocupa banda liberă dintre el și un alt vehicul. Prin urmare, varianta C este incorectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1201.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1201.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1201; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1200 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pe-drumurile-publice-prevazute-cu-minimum-3-benzi-pe-sens-atunci-cand-conducatorii-a-doua-vehicule-circula-in-aceeasi-directie-dar-pe-benzi-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1200","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1202","batch":"25","category":"Categoria B","question":"Frâna de serviciu a autovehiculului trebuie să aibă capacitatea de a asigura:","answers":["Funcționarea în bune condiții a frânelor de la roțile motoare","Încetinirea și oprirea rapidă, sigură și eficace, indiferent de gradul de încărcare a autovehiculului și de înclinarea drumului","Imobilizarea vehiculului pe timpul staționării sau al parcării îndelungate"],"correctIndices":[1],"correct":1,"explanation":"Frâna de serviciu, cunoscută și sub denumirea de frână de picior, are rolul de a încetini și opri autovehiculul în condiții de siguranță, indiferent de sarcina transportată sau de configurația drumului. Un sistem de frânare eficient trebuie să permită o oprire rapidă, dar controlată, fără riscul de a pierde aderența sau stabilitatea vehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1202.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1202.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1202; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1201 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/frana-de-serviciu-a-autovehiculului-trebuie-sa-aiba-capacitatea-de-a-asigura","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1201","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1203","batch":"25","category":"Categoria B","question":"Ce informații oferă indicatorul din imagine?","answers":["Urmează un pasaj denivelat, la 3 km distanță de tunel","Urmează un tunel, la 3 km distanță de indicator","Tunelul care urmează are o lungime de 3 km"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul informează conducătorii de vehicule despre apropierea de un tunel și specifică lungimea acestuia, care în acest caz este de 3 km. Acesta nu informează despre distanța până la tunel sau despre un alt tip de pasaj, cum ar fi un pasaj denivelat. Această informație este importantă pentru conducătorii de vehicule care se pot pregăti din timp pentru intrarea într-un tunel adaptându-și stilul de conducere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1203.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1203.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1203; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul pătrat albastru cu simbolul unui tunel și inscripția '3 km'.","needsImageReview":true,"source":"RoDrive · ID 1202 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-informatii-ofera-indicatorul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1202","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1215.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1204","batch":"25","category":"Categoria B","question":"Cine are prioritate atunci când două vehicule ce au în funcțiune mijloacele speciale de avertizare luminoase și sonore, se întâlnesc la intrarea într-o intersecție dirijată prin indicatoare și întâlnesc indicatoare ce au aceeași semnificație?","answers":["Vehiculul care circulă din partea dreaptă","Autovehiculul aparținând poliției","Autovehiculul aparținând serviciului de ambulanță sau medicină legală"],"correctIndices":[0],"correct":0,"explanation":"Atunci când două vehicule cu regim de circulație prioritară (de exemplu, poliție, pompieri, ambulanță sau medicină legală) se întâlnesc într-o intersecție și ambele se deplasează în misiune având semnalele luminoase și sonore în funcțiune, prioritatea se acordă vehiculului care circulă din partea dreaptă. Această regulă se aplică indiferent de tipul vehiculelor implicate, fie că este vorba de vehicule ale poliției, ale pompierilor, ale serviciului de ambulanță sau medicină legală, ori alte vehicule cu regim de circulație prioritară care se deplasează în misiune având semnalele luminoase și sonore în funcțiune. Principiul este simplu și se bazează pe regula generală de prioritate „prioritatea de dreapta”, care este una dintre regulile fundamentale de circulație în intersecții. Prioritatea nu se acordă în funcție de tipul vehiculului (poliție, ambulanță, etc.) sau de culoare semnalelor luminoase cu care acestea sunt prevăzute (roșu sau albastru), ci în funcție de poziția acestuia în raport cu celălalt vehicul la intrarea în intersecție, astfel prioritatea se acordă vehiculului care circulă din partea dreaptă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1204.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1204.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1204; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1203 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cine-are-prioritate-atunci-cand-doua-vehicule-ce-au-in-functiune-mijloacele-speciale-de-avertizare-luminoase-si-sonore-se-intalnesc-la-intra","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1203","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1205","batch":"25","category":"Categoria B","question":"Cum procedați la întâlnirea indicatorului și a panoului adițional?","answers":["Treceți primul prin intersecție","Cedați trecerea vehiculelor care vin de pe drumul prioritar","Cedați trecerea tuturor vehiculelor"],"correctIndices":[1],"correct":1,"explanation":"În această situație întâlniți indicatorul “Cedează trecerea” însoțit de un panou adițional care vă indică direcția drumului cu prioritate, în situația dată trebuie să acordați prioritate vehiculelor care vin de pe drumul cu prioritate. Vehiculele care vin din partea stângă trebuie să vă acorde prioritate, deoarece se creează o situație de egalitate, situație în care trebuie aplicată regula priorității de dreapta. Prin urmare, în această situație trebuie să cedați trecerea vehiculelor care vin de pe drumul prioritar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1205.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1205.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1205; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular,'Cedează trecerea', împreună cu panoul adițional ce descrie configurația intersecției și drumul prioritar.","needsImageReview":true,"source":"RoDrive · ID 1204 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-la-intalnirea-indicatorului-si-a-panoului-aditional","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1204","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1237.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1206","batch":"25","category":"Categoria B","question":"Ce date are obligația de a comunica poliției rutiere sau a poliției locale proprietarul sau deținătorul mandatat al unui vehicul, la solicitarea acestora, cu privire la persoana căreia i-a încredințat vehiculul pentru a-l conduce pe drumurile publice?","answers":["Numele, data și locul nașterii, precum și localitatea unde persoana respectivă a condus vehiculul","Numele, prenumele, codul numeric personal, domiciliul sau reședința, numărul și seria actului de identitate a persoanei respective, iar în cazul cetățenilor străini și seria și numărul pașaportului, data eliberării acestuia și statul emitent","Copii ale actului de identitate și pașaportului persoanei respective"],"correctIndices":[1],"correct":1,"explanation":"La solicitarea poliției rutiere sau a poliției locale, proprietarul sau deținătorul mandatat al unui vehicul este obligat să comunice acesteia, în termenul indicat în cuprinsul solicitării, datele de identificare ale persoanei căreia i-a încredințat vehiculul pentru a-l conduce pe drumurile publice. Datele de identificare ce trebuie comunicate sunt:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1206.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1206.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1206; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1205 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-date-are-obligatia-de-a-comunica-politiei-rutiere-sau-a-politiei-locale-proprietarul-sau-detinatorul-mandatat-al-unui-vehicul-la-solicita","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1205","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1207","batch":"25","category":"Categoria B","question":"Pentru care dintre faptele de mai jos se aplică amenda prevăzută în clasa a III-a de sancțiuni și suspendarea dreptului de a conduce pentru o perioada de 60 de zile?","answers":["Implicarea într-un accident de circulație din care au rezultat numai avarierea unui vehicul sau alte pagube materiale","Depășirea coloanelor de vehicule oprite la culoarea roșie a semaforului","Adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publice, dacă prin aceasta s-a produs un accident de circulație din care au rezultat avarierea unui vehicul sau alte pagube materiale"],"correctIndices":[2],"correct":2,"explanation":"Adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publice se sancționează cu amenda prevăzută înclasaa II-ade sancțiuniși cu suspendarea dreptului de a conducepentru o perioadă de30 de zile. Însă dacă prin adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publices-a produs un accident de circulație din care au rezultat avarierea unui vehicul sau alte pagube materiale(însemnând un accident rutier fără victime), se va sancționa mai „aspru”, cu amenda prevăzută înclasaa III-ade sancțiuniși cu suspendarea dreptului de a conducepentru o perioada de60 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1207.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1207.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1207; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1206 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-care-dintre-faptele-de-mai-jos-se-aplica-amenda-prevazuta-in-clasa-a-iii-a-de-sanctiuni-si-suspendarea-dreptului-de-a-conduce-pentru-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1206","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1208","batch":"25","category":"Categoria B","question":"Cum se sancționează conducerea unei trotinete electrice pe autostradă?","answers":["Cu aplicarea punctelor de penalizare","Cu amenda prevăzută în clasa a iii-a de sancțiuni","Cu suspendarea dreptului de a conduce autovehicule pentru o perioada de 30 de zile"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră interzice circulația trotinetelor electrice pe autostradă, iar încălcarea acestei reguli este considerată contravenție și se sancționează cu amenda prevăzută în clasa a III-a de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1208.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1208.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1208; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1207 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-sanctioneaza-conducerea-unei-trotinete-electrice-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1207","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
